        lifecycle: "working",
      },
    },
    unreadTabIds: {},
    unreadWorktreePaths: {},
    activityBySessionId: {},
    layout: {
      tabs: [
        { id: "tab-terminal", label: "Terminal", sessionId: "terminal" },
        {
          id: "tab-browser",
          kind: "browser",
          label: "Docs",
